question.sparql:
PREFIX fcd:  <https://example.org/fincrime-data#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?system ?flag ?technique ?score WHERE {
  ?alert fcd:alertedTransaction <https://example.org/transaction/5007762> ;
         fcd:sourceSystem ?system .
  OPTIONAL { ?alert fcd:firedFlag ?flag . ?flag rdfs:seeAlso ?technique }
  OPTIONAL { ?alert fcd:mlScore ?score }
}

r2rml:
@prefix rr:  <http://www.w3.org/ns/r2rml#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix fcd: <https://example.org/fincrime-data#> .
@prefix map: <https://example.org/obda/alerts#> .

# DRAFT written for this demo (OBDA design, not run). An R2RML mapping (W3C Recommendation) from the three alert tables to the
# FinCrime data ontology in alert_ontology.ttl, so that an alert looks the same whichever system raised it. It is declarative:
# an engine such as Ontop would apply it to rewrite a query on the terms into SQL on the tables. Nothing here runs yet.
#
# Each table is mapped for what its own system says: the rule table for its flags, the ML table for its score, the graph table for
# the round trip. The tables also carry the signals of the other systems (they are all cut from one feature table), but those are
# not read here, so no alert claims something its own system did not say. The payment itself is described by the mapping of the
# transaction table (txs.r2rml.ttl): the alert only points to it. The laundering label is not mapped.

# ---------------------------------------------------------------- rule engine
map:RuleAlertMap a rr:TriplesMap ;
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ; rr:class fcd:Alert ] ;
    rr:predicateObjectMap
        [ rr:predicate fcd:sourceSystem ;        rr:objectMap [ rr:constant "rule engine" ] ] ,
        [ rr:predicate fcd:alertedTransaction ;  rr:objectMap [ rr:template "https://example.org/transaction/{tx_id}" ; rr:termType rr:IRI ] ] .

map:RuleFlagStructuringMap a rr:TriplesMap ;   # one mapping per flag: the alert gets the flag when the rule fired
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule WHERE rule_structuring = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_structuring ] .

map:RuleFlagMoneyMuleMap a rr:TriplesMap ;   # one mapping per flag: the alert gets the flag when the rule fired
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule WHERE rule_money_mule = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_money_mule ] .

map:RuleFlagFanInMap a rr:TriplesMap ;   # one mapping per flag: the alert gets the flag when the rule fired
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule WHERE rule_fan_in = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_fan_in ] .

map:RuleFlagPepMap a rr:TriplesMap ;   # one mapping per flag: the alert gets the flag when the rule fired
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule WHERE rule_pep = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_pep ] .

map:RuleFlagHighRiskBusinessMap a rr:TriplesMap ;   # one mapping per flag: the alert gets the flag when the rule fired
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule WHERE rule_high_risk_business = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_high_risk_business ] .

map:RuleFlagHighRiskCountryMap a rr:TriplesMap ;   # one mapping per flag: the alert gets the flag when the rule fired
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_rule WHERE rule_high_risk_country = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/rule/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_high_risk_country ] .

# ---------------------------------------------------------------- ML model
map:MlAlertMap a rr:TriplesMap ;
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id, ml_proba FROM alert_ml" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/ml/{tx_id}" ; rr:class fcd:Alert ] ;
    rr:predicateObjectMap
        [ rr:predicate fcd:sourceSystem ;        rr:objectMap [ rr:constant "ML model" ] ] ,
        [ rr:predicate fcd:alertedTransaction ;  rr:objectMap [ rr:template "https://example.org/transaction/{tx_id}" ; rr:termType rr:IRI ] ] ,
        [ rr:predicate fcd:mlScore ;             rr:objectMap [ rr:column "ml_proba" ; rr:datatype xsd:float ] ] .

# ---------------------------------------------------------------- transaction graph
map:GraphAlertMap a rr:TriplesMap ;
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_graph" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/graph/{tx_id}" ; rr:class fcd:Alert ] ;
    rr:predicateObjectMap
        [ rr:predicate fcd:sourceSystem ;        rr:objectMap [ rr:constant "transaction graph" ] ] ,
        [ rr:predicate fcd:alertedTransaction ;  rr:objectMap [ rr:template "https://example.org/transaction/{tx_id}" ; rr:termType rr:IRI ] ] .

map:GraphFlagRoundtripMap a rr:TriplesMap ;
    rr:logicalTable [ rr:sqlQuery "SELECT tx_id FROM alert_graph WHERE graph_roundtrip = 1" ] ;
    rr:subjectMap [ rr:template "https://example.org/alert/graph/{tx_id}" ] ;
    rr:predicateObjectMap [ rr:predicate fcd:firedFlag ; rr:object fcd:flag_roundtrip ] .

ontology:
@prefix fcd:  <https://example.org/fincrime-data#> .
@prefix amx:  <https://example.org/amltrix/> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix dct:  <http://purl.org/dc/terms/> .

# DRAFT written for this demo (OBDA design, not run). The ontology side of an OBDA setup for the three alert tables of the
# detection systems (rule engine, ML model, transaction graph): the terms every alert is described with, whichever system
# raised it. It builds on transaction_ontology.ttl (fcd:Transaction). The mapping that ties the terms to the tables is
# alerts.r2rml.ttl. The namespace is a placeholder.

<https://example.org/fincrime-data/alerts> a owl:Ontology ;
    dct:title "FinCrime data ontology, alerts (Demo)"@en ;
    owl:imports <https://example.org/fincrime-data> ;
    owl:versionInfo "0.1-draft" .

fcd:Alert a owl:Class ;
    rdfs:label "Alert"@en ;
    rdfs:comment "One detection system flagged one payment. The same payment can have one alert from each system."@en .

fcd:Flag a owl:Class ;
    rdfs:label "Flag"@en ;
    rdfs:comment "A reason a detection system gives for an alert: one of the six rules, or the round trip found by the transaction graph."@en .

fcd:alertedTransaction a owl:ObjectProperty ;
    rdfs:label "alerted transaction"@en ;
    rdfs:comment "The payment the alert is about."@en ;
    rdfs:domain fcd:Alert ; rdfs:range fcd:Transaction .

fcd:sourceSystem a owl:DatatypeProperty ;
    rdfs:label "source system"@en ;
    rdfs:comment "The detection system that raised the alert: the rule engine, the ML model or the transaction graph."@en ;
    rdfs:domain fcd:Alert ; rdfs:range xsd:string .

fcd:firedFlag a owl:ObjectProperty ;
    rdfs:label "fired flag"@en ;
    rdfs:comment "A reason the alert gives. The rule engine can give several; the transaction graph gives the round trip; the ML model gives none, only a score."@en ;
    rdfs:domain fcd:Alert ; rdfs:range fcd:Flag .

fcd:mlScore a owl:DatatypeProperty ;
    rdfs:label "ML score"@en ;
    rdfs:comment "The probability the ML model gave the payment. A score, not a reason."@en ;
    rdfs:domain fcd:Alert ; rdfs:range xsd:float .

# The flags. rdfs:seeAlso points to the AML typology technique that the first-pass draft mapping of the demo (alert_sources.json,
# not reviewed by a domain expert) lists first, the strongest, for the flag.

fcd:flag_structuring a fcd:Flag ;
    rdfs:label "Structuring"@en ;
    rdfs:comment "Same account makes 2 or more same-day transactions in the $8,500-$10,000 range."@en ;
    rdfs:seeAlso amx:T0016 .   # strong

fcd:flag_money_mule a fcd:Flag ;
    rdfs:label "Gather-Scatter"@en ;
    rdfs:comment "An inflow of at least $3,000 followed within 3 days by an outflow of at least 85% of it from the same account (rapid pass-through)."@en ;
    rdfs:seeAlso amx:T0011 .   # strong

fcd:flag_fan_in a fcd:Flag ;
    rdfs:label "Fan-In"@en ;
    rdfs:comment "The receiving account collects funds from 5 or more distinct counterparties on the same day."@en ;
    rdfs:seeAlso amx:T0083 .   # medium

fcd:flag_pep a fcd:Flag ;
    rdfs:label "PEP"@en ;
    rdfs:comment "Either party's KYC record carries a PEP flag. A customer-risk flag, not a behavioural pattern."@en ;
    rdfs:seeAlso amx:T0051 .   # medium

fcd:flag_high_risk_business a fcd:Flag ;
    rdfs:label "High-Risk Business"@en ;
    rdfs:comment "Either party's declared industry is Money Service Business, Cryptocurrency Exchange, Casino & Gaming, Precious Metals & Jewelry, or Import/Export Trading."@en ;
    rdfs:seeAlso amx:T0055 .   # strong

fcd:flag_high_risk_country a fcd:Flag ;
    rdfs:label "High-Risk Country"@en ;
    rdfs:comment "Payment currency is Ruble or Mexican Peso, used as a jurisdiction proxy because the dataset has no country field."@en ;
    rdfs:seeAlso amx:T0141 .   # medium

fcd:flag_roundtrip a fcd:Flag ;
    rdfs:label "Round-trip"@en ;
    rdfs:comment "A verified, time-ordered cycle of 3-5 hops where funds return to the originating account."@en ;
    rdfs:seeAlso amx:T0039 .   # strong
